        if log_hash in seen:
            continue
        seen.add(log_hash)
        yield log

# Sample Data
logs = [
    {'id': '1234', 'error': None, 'fruit': 'orange'},
    {'id': '12345', 'error': None, 'fruit': 'apple'},
    {'id': '1234', 'error': None, 'fruit': 'orange'},  # Duplicate
]

# Test
print(list(deduplicate(logs)))


[{'id': '1234', 'error': None, 'fruit': 'orange'},
 {'id': '12345', 'error': None, 'fruit': 'apple'}]

