import keyword

def is_valid_identifier(key):
    return key.isidentifier() and not keyword.iskeyword(key)

def foo(**kwargs):
    for key in kwargs:
        if not is_valid_identifier(key):
            raise ValueError(f"Invalid identifier: {key}")
    print(kwargs)

try:
    foo(**{"a": 3, "b": 2, "not valid": 4})
except ValueError as e:
    print(e)

